import java.net.URI;
import java.util.HashMap;
import java.util.Map;

public class PlaceholderGenerator {
    public static String getPlaceholder(int width, int height) throws Exception {
        URI url = new URI("https://img.automators.work/" + width + "x" + height + "?bg=" + hex6);
        Map<String, String> params = new HashMap<>();
        params.put("width", Integer.toString(width));
        params.put("height", Integer.toString(height));
        return url.getQuery();
    }

    public static void main(String[] args) throws Exception {
        System.out.println(getPlaceholder(800, 450));
    }
}
